import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"9. Setting Up a Minimal Project Structure","description":"The Little Book of C — 9. Setting Up a Minimal Project Structure","frontmatter":{"title":"9. Setting Up a Minimal Project Structure","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 9. Setting Up a Minimal Project Structure","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":9,"sidebarWeight":9,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure","alternateZh":"/posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure.md","filePath":"posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure.md"};function p(o,e,l,c,r,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure)</p><p>As your C programs grow, you’ll quickly outgrow the single-file “hello.c” style. Real projects are made of multiple source files, headers, and sometimes libraries. A clear folder structure keeps your work clean, easy to build, and easy to maintain. In this section, you’ll create a small, organized layout, the same structure used by professionals.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a minimal project layout:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my_project/</span></span>
<span class="line"><span>├── include/</span></span>
<span class="line"><span>│   └── greet.h</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   └── greet.c</span></span>
<span class="line"><span>├── main.c</span></span>
<span class="line"><span>└── Makefile</span></span></code></pre></div><p>include/greet.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef GREET_H</span></span>
<span class="line"><span>#define GREET_H</span></span>
<span class="line"><span>void greet(const char *name);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>src/greet.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C Learner&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -Iinclude</span></span>
<span class="line"><span>SRC = main.c src/greet.c</span></span>
<span class="line"><span>OUT = my_program</span></span>
<span class="line"><span>$(OUT): $(SRC)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(SRC) -o $(OUT)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OUT)</span></span></code></pre></div><p>Now build and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./my_program</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C Learner!</span></span></code></pre></div><h4 id="understanding-the-structure" tabindex="-1">Understanding the Structure <a class="header-anchor" href="#understanding-the-structure" aria-label="Permalink to &quot;Understanding the Structure&quot;">​</a></h4><p><code>include/</code> Holds header files (<code>.h</code>), declarations of functions, constants, and types. You include these in<code>.c</code> files using quotes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span></code></pre></div><p><code>src/</code> Contains source files (<code>.c</code>) that implement functions declared in headers.</p><p><code>main.c</code> The entry point of your program, this file usually just calls functions from<code>src/</code>.</p><p><code>Makefile</code> Defines how to build the program. You can run<code>make</code> instead of typing long<code>gcc</code> commands.</p><p>Output binary The compiled executable (here<code>my_program</code>) stays in the project’s root for convenience.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>A clear structure helps you:</p><ul><li>Keep code modular and reusable</li><li>Separate interface (<code>.h</code>) from implementation (<code>.c</code>)</li><li>Make compilation faster and easier to manage</li><li>Avoid name clashes in large projects</li><li>Scale from one file to dozens without confusion</li></ul><p>Even small C utilities benefit from structure, you’ll thank yourself later when you revisit your code.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Create the directories and files shown above.</p><p>Type each file carefully and run<code>make</code>.</p><p>Modify<code>greet.c</code> to print a personalized message, e.g.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Welcome back, %s!\\n&quot;, name);</span></span></code></pre></div><p>then rebuild.</p><p>Add another pair of files,<code>src/farewell.c</code> and<code>include/farewell.h</code>, with a goodbye function, and call it from<code>main.c</code>.</p><p>Run<code>make clean</code> to delete the binary and rebuild fresh.</p><p>This small structure is the seed of every serious C project. Once you can organize your files this way, you’re ready to grow into larger systems, libraries, tools, and applications that others can use and build upon.</p>`,37)])])}const g=a(i,[["render",p]]);export{h as __pageData,g as default};
